    question: '建設機械の走行性（トラフィカビリティ）と土の含水比の関係に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'トラフィカビリティとは、建設機械が地盤上を走行できる能力（走行性）をいい、一般にコーン指数を目安として評価される。', explanation: '適当。トラフィカビリティの定義である。' },
      { key: 'B', text: '含水比が高くなるほど、一般に土のコーン指数は低下し、建設機械のトラフィカビリティは悪化する傾向がある。', explanation: '適当。含水比とコーン指数の一般的な関係である。' },
      { key: 'C', text: '降雨等により含水比が上昇し軟弱化した地盤では、機械の走行に必要なコーン指数を確保するため、敷き鉄板の設置や表層の地盤改良等の対策が有効である。', explanation: '適当。軟弱化した地盤への対策として妥当である。' },
      { key: 'D', text: 'トラフィカビリティは使用する建設機械の種類（接地圧）にかかわらず一定であり、必要なコーン指数の基準値も機種によらず同一の値を用いる。', explanation: '不適当。必要なコーン指数の目安は、機械の接地圧（普通ブルドーザ・湿地ブルドーザ・ダンプトラック等）によって異なり、機種ごとに基準値が設定される。機種によらず同一とする記述は不適当。' },
    ],
    correctKey: 'D',
    explanation: 'トラフィカビリティは建設機械が地盤上を走行できる能力で、ポータブルコーン貫入試験で得られるコーン指数を目安として判定する。必要なコーン指数は機械の接地圧によって異なり、接地圧が小さい湿地ブルドーザは300kN/m²程度、普通ブルドーザは500から700kN/m²程度、接地面積の小さいダンプトラックは1200kN/m²以上が目安となる。土の含水比が上がるとせん断強度が落ちてコーン指数も低下するため、降雨後は走行不能になりやすい。対策には排水、敷鉄板や敷砂利、表層混合処理があり、接地圧の小さい機種への変更も有効である。\n【図解】トラフィカビリティの考え方\n　項目｜内容｜要点\n　判定指標｜コーン指数｜ポータブルコーン貫入試験\n　含水比の影響｜高いほどコーン指数が低下｜降雨後は走行が困難\n　対策｜排水、敷鉄板、表層改良｜接地圧の小さい機種へ変更\n　⇒ 必要コーン指数は接地圧に応じて機種ごとに異なる\n　⚠ 機種によらず基準値が同一という記述は誤り',
    difficulty: 'basic',
