    choices: [
      { key: 'A', text: '杭の水平載荷試験は、杭頭に水平方向の荷重を段階的に加え、水平荷重と水平変位の関係から杭の水平地盤反力係数等を求める試験である。', explanation: '適当。水平載荷試験の基本内容である。' },
      { key: 'B', text: '水平地盤反力係数は、橋脚基礎等における地震時の水平抵抗性能（耐震設計）の検討に用いられる重要な定数である。', explanation: '適当。水平地盤反力係数の用途として妥当である。' },
      { key: 'C', text: '杭の水平抵抗は、杭周面の地盤の水平方向のばね反力によって評価されることが多く、杭本体の曲げ剛性（EI）も応答に影響する。', explanation: '適当。水平抵抗の評価方法として妥当である。' },
      { key: 'D', text: '杭の水平抵抗は、鉛直支持力（先端支持力・周面摩擦力）の値から直接換算でき、別途水平載荷試験を行う必要はない。', explanation: '不適当。水平抵抗は鉛直支持力とは異なるメカニズム（周面地盤の水平方向反力・杭体の曲げ剛性）に支配されるため、鉛直支持力の値から直接換算することはできない。' },
    ],
    correctKey: 'D',
