    question: '掘削工事に伴う周辺地盤への影響と近接施工管理に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '土留め壁のたわみや根入れ不足等により、掘削背面の地盤に沈下や変位が生じることがあり、近接構造物への影響が懸念される。', explanation: '適当。近接施工における懸念事項として妥当である。' },
      { key: 'B', text: '近接施工では、周辺地盤・構造物の変位計測（傾斜計・沈下計等）を行い、あらかじめ設定した管理値と比較して施工の安全性を確認する管理体制（計測管理）が重要である。', explanation: '適当。近接施工管理の基本的な考え方である。' },
      { key: 'C', text: '掘削による周辺地盤の変位を抑制するためには、土留め壁の剛性を高める、切梁の段数を増やす、根入れ長を確保する等の対策が有効である。', explanation: '適当。周辺地盤変位の抑制対策として妥当である。' },
      { key: 'D', text: '近接施工における周辺地盤への影響は、あらかじめ設定した管理値を一度でも超えた場合であっても、工事の進捗を優先し、対策を講じずにそのまま掘削を継続してよい。', explanation: '不適当。管理値を超過した場合は、施工の一時中断や補強対策の実施等、適切な対応をとる必要があり、対策を講じずに施工を継続することは不適当である。' },
    ],
    correctKey: 'D',
    explanation: '掘削に伴って土留め壁がたわみ、あるいは根入れ不足によりヒービングやボイリングが生じると、背面地盤が沈下して近接構造物に傾斜やひび割れをもたらす。このため近接施工では、着工前に家屋調査などの事前調査を行ったうえで、傾斜計、沈下計、壁体変位計、地下水位計を配置し、一次管理値や二次管理値といった段階的な管理値をあらかじめ定めて計測管理を行う。管理値を超えた場合は掘削を中断し、原因を調査して切ばりの増設や地盤改良などの補強対策を講じてから再開するのが原則である。\n【図解】近接施工の計測管理\n　段階｜行うこと｜内容\n　着工前｜事前調査と管理値の設定｜家屋調査と計測計画\n　施工中｜変位と沈下の計測｜計画値との比較\n　管理値の超過時｜掘削の中断と対策｜切ばり増設や地盤改良\n　⇒ 変位抑制には壁の剛性、切ばり段数、根入れ長が効く\n　⚠ 管理値を超えてもそのまま掘削を継続してよいという記述は誤り',
    difficulty: 'basic',
