    question: 'セメント系安定処理工法（機械撹拌方式・高圧噴射撹拌方式）に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'セメント系安定処理工法には、施工機械により地盤とセメント系固化材を撹拌混合する機械撹拌方式と、高圧噴射により地盤を切削しながら固化材を混合する高圧噴射撹拌方式がある。', explanation: '適当。セメント系安定処理の分類として妥当である。' },
      { key: 'B', text: '機械撹拌方式は、撹拌翼により土とバインダー（セメント系固化材）を直接混合するため、比較的均質な改良体を得やすい。', explanation: '適当。機械撹拌方式の特徴として妥当である。' },
      { key: 'C', text: '高圧噴射撹拌方式は、機械撹拌方式に比べて硬質な地盤や狭隘な場所への適用が難しく、施工範囲が限定される。', explanation: '不適当。逆である。高圧噴射撹拌方式は、機械撹拌方式では施工が難しい狭隘な場所や既設構造物近接部等でも適用しやすいという利点があるとされる。' },
      { key: 'D', text: 'セメント系固化材の添加量は、対象土の種類（有機質土等）や含水比、目標とする強度に応じて、事前の配合試験により設定する。', explanation: '適当。添加量設定の考え方として妥当である。' },
    ],
    correctKey: 'C',
    explanation: 'セメント系安定処理には、撹拌翼を回転させて原位置土と固化材を直接混ぜる機械撹拌方式と、高圧のスラリーで地盤を切削しながら混合する高圧噴射撹拌方式がある。機械撹拌方式は翼が土を確実に練り混ぜるため均質な改良体が得られ経済的だが、大型の施工機械が必要で、狭い場所や既設構造物の直下、近接部には入れない。高圧噴射撹拌方式は小径のロッドで施工できるので、狭あい地や近接施工、硬質な地盤でも適用しやすい。固化材の添加量は対象土の種類と含水比、目標強度に応じ、事前の配合試験で定める。\n【図解】機械撹拌方式と高圧噴射撹拌方式\n　項目｜機械撹拌方式｜高圧噴射撹拌方式\n　混合の方法｜撹拌翼で直接練り混ぜる｜高圧噴射で切削し混合\n　改良体の均質性｜比較的均質になりやすい｜噴射条件に左右される\n　狭あい地や近接施工｜大型機械のため不利｜適用しやすい\n　⇒ 固化材の添加量は事前の配合試験で設定する\n　⚠ 高圧噴射方式が狭あい地に適用しにくいという記述は逆',
    difficulty: 'standard',
