    question: '石灰安定処理・生石灰杭工法に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '石灰安定処理は、生石灰又は消石灰を土に混合し、化学反応（水和反応・ポゾラン反応）による脱水・固化効果で地盤の強度を改善する工法である。', explanation: '適当。石灰安定処理の原理である。' },
      { key: 'B', text: '生石灰は水と反応する際に発熱・膨張するため、高含水比の粘性土に対して即効的な含水比低下効果が期待できる。', explanation: '適当。生石灰の反応特性として妥当である。' },
      { key: 'C', text: '生石灰杭工法は、地盤中に生石灰の杭を造成し、周辺地盤の水分を吸収させることで、地盤の圧密・強度増加を促進する工法である。', explanation: '適当。生石灰杭工法の原理として妥当である。' },
      { key: 'D', text: '石灰安定処理の効果は添加する石灰の種類・添加量にかかわらず一定であり、事前の配合試験を行わずに、どの現場でも同一の添加量を適用してよい。', explanation: '不適当。安定処理の効果は土質・含水比・石灰の種類等により異なるため、事前の配合試験（室内試験）により適切な添加量を設定する必要がある。' },
    ],
    correctKey: 'D',
    explanation: '石灰安定処理は、生石灰や消石灰を土に混合し、消化反応による吸水と発熱、イオン交換による団粒化、さらに長期のポゾラン反応による固化によって強度を改善する工法である。生石灰は水と反応する際に多量の水を消費し発熱と膨張を伴うため、高含水比の粘性土の含水比を即効的に下げるのに適する。生石灰杭工法は、地盤中に生石灰の杭を造成し周辺土の水分を吸収させて膨張させることで、脱水と圧密、強度増加を促す。添加量は土質、含水比、石灰の種類、目標強度により変わるので、必ず室内配合試験で決定する。\n【図解】石灰安定処理の反応と効果\n　段階｜反応｜効果\n　直後｜生石灰の消化反応｜吸水と発熱で含水比が低下\n　短期｜イオン交換による団粒化｜こね返しに強くなり施工性向上\n　長期｜ポゾラン反応｜強度が徐々に増加する\n　⇒ 高含水比の粘性土には生石灰の即効的な脱水が有効\n　⚠ 配合試験なしに全現場で同一添加量としてよいという記述は誤り',
    difficulty: 'standard',
