    question: '高含水比粘性土の盛土施工対策に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '高含水比の粘性土は、締固めが困難でトラフィカビリティも悪化しやすいため、そのままでは盛土材料として不適当な場合が多い。', explanation: '適当。高含水比粘性土の一般的な性質として妥当である。' },
      { key: 'B', text: '対策として、天日等によるばっ気乾燥、石灰・セメント系固化材による安定処理、良質土との混合等により、施工性・強度を改善する方法がある。', explanation: '適当。高含水比粘性土への代表的な対策である。' },
      { key: 'C', text: 'サンドマットや敷き鉄板の設置は、機械の接地圧を分散させ、トラフィカビリティを確保するための対策として有効である。', explanation: '適当。トラフィカビリティ確保策として妥当である。' },
      { key: 'D', text: '高含水比の粘性土は、含水比調整等の対策を行わなくても、締固めエネルギーを大幅に増加させることで、必ず所要の締固め度を確保できる。', explanation: '不適当。高含水比の粘性土は間隙が水で満たされ空気間隙率が小さいため、締固めエネルギーを増加させても密度がほとんど増加しない領域があり、含水比調整等の対策なしに締固めエネルギーの増大のみで解決できるとは限らない。' },
    ],
    correctKey: 'D',
    explanation: '高含水比の粘性土は、間隙がほぼ水で満たされて空気間隙率が小さいため、締固めエネルギーを増やしても密度がほとんど上がらず、かえってこね返しにより強度が低下することがある。したがってエネルギーの増大だけでは解決できず、含水比そのものを下げる対策が必要になる。天日によるばっ気乾燥、トレンチ掘削による排水、生石灰やセメント系固化材による安定処理、良質土との混合が代表的な方法である。あわせてサンドマットや敷鉄板により接地圧を分散し、施工機械の走行性を確保することも有効である。\n【図解】高含水比粘性土への対策\n　対策｜内容｜ねらい\n　ばっ気乾燥｜天日乾燥やトレンチ排水｜含水比そのものを下げる\n　安定処理｜石灰やセメント系固化材｜脱水と強度の改善\n　走行性の確保｜サンドマットや敷鉄板｜接地圧の分散\n　⇒ 含水比を最適含水比付近に近づけることが本質\n　⚠ 締固めエネルギーの増加だけで必ず所要密度が得られるという記述は誤り',
    difficulty: 'standard',
