    id: 'ks-doboku-249', subject: 'doboku', subjectName: '土木工学',
    question: 'AE剤（空気連行剤）とコンクリートの空気量に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'AE剤（空気連行剤）は、コンクリート中に微細な独立した空気泡（エントレインドエア）を連行させ、コンクリートのワーカビリティーの改善や耐凍害性の向上を図る混和剤である。', explanation: '適当。AE剤の目的として妥当である。' },
      { key: 'B', text: '空気量が多すぎると、コンクリートの圧縮強度が低下する傾向があるため、所要のワーカビリティー・耐凍害性が得られる範囲で適切な空気量（一般に4〜7％程度）に管理する。', explanation: '適当。空気量管理の考え方として妥当である。' },
      { key: 'C', text: '空気量試験には、エアメータによる方法（空気室圧力法等）が用いられ、フレッシュコンクリートの受入れ検査項目の一つとされる。', explanation: '適当。空気量試験の位置づけとして妥当である。' },
      { key: 'D', text: 'AE剤による連行空気（エントレインドエア）は、練混ぜ不足等により生じる粗大な気泡（エントラップトエア）と同様の性質を持ち、両者を区別して管理する必要はない。', explanation: '不適当。エントレインドエアは微細で独立した気泡でワーカビリティー改善・耐凍害性向上に寄与する良好な空気であるのに対し、エントラップトエアは練混ぜ不足等で生じる粗大な気泡で強度低下等の悪影響を及ぼしやすく、両者は性質が異なるため区別して考える必要がある。' },
    ],
    correctKey: 'D',
    explanation: 'AE剤による微細な連行空気（良い空気）と、練混ぜ不足による粗大な巻き込み空気（悪い空気）は性質が全く異なる。同一視するのは誤り。\n【図解】空気量管理の要点\n　エントレインドエア：AE剤による微細・独立気泡★→耐凍害性・ワーカビリティー向上に有効\n　エントラップトエア：練混ぜ不足等の粗大気泡★→強度低下等の悪影響\n　○適正空気量の目安：一般に4〜7％程度\n　×「両者は同様の性質で区別不要」は誤り★\n　→良い空気（微細）と悪い空気（粗大）は明確に区別',
    difficulty: 'advanced',
