    question: '鉄筋の継手（重ね継手・ガス圧接継手・機械式継手）に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '重ね継手は、鉄筋を一定の長さ重ね合わせ、コンクリートとの付着力を利用して応力を伝達する継手であり、比較的細い鉄筋に用いられる。', explanation: '適当。重ね継手の特徴として妥当である。' },
      { key: 'B', text: 'ガス圧接継手は、鉄筋端部をガス炎で加熱し、軸方向に圧力を加えて接合する継手であり、太径の鉄筋にも適用できる。', explanation: '適当。ガス圧接継手の特徴として妥当である。' },
      { key: 'C', text: '機械式継手（スリーブ継手等）は、専用のスリーブ・カプラー等を用いて鉄筋を接合する継手であり、圧接技能に依存しにくいという特徴がある。', explanation: '適当。機械式継手の特徴として妥当である。' },
      { key: 'D', text: '鉄筋の継手位置は、部材に生じる応力の大きさにかかわらず、施工上都合の良い位置に自由に設けてよく、応力集中や継手位置の分散等を考慮する必要はない。', explanation: '不適当。継手位置は、応力の大きい断面への集中を避け、同一断面に継手が集中しないよう分散させる（継手位置の千鳥配置等）等、構造性能を確保するための配慮が必要である。' },
    ],
    correctKey: 'D',
    explanation: '鉄筋の継手には、所要の長さを重ねて付着で応力を伝える重ね継手、端部を加熱して軸方向に加圧し一体化するガス圧接継手、スリーブやカプラーで接合する機械式継手がある。重ね継手は施工が容易だが太径では重ね長が長くなり配筋が過密になるため、太径にはガス圧接や機械式が用いられる。いずれの継手も母材に比べ弱点になりやすいので、位置は応力の小さい断面に設け、同一断面に集中しないよう軸方向にずらして千鳥に配置する。圧接部のふくらみや偏心の検査も欠かせない。\n【図解】鉄筋継手の種類と特徴\n　継手｜応力の伝達｜適用\n　重ね継手｜コンクリートとの付着｜比較的細径の鉄筋\n　ガス圧接継手｜加熱と加圧による一体化｜太径にも適用できる\n　機械式継手｜スリーブやカプラーによる｜技能への依存が小さい\n　⇒ 継手は応力の小さい断面に設け千鳥に分散配置する\n　⚠ 応力に関係なく施工の都合で自由に配置してよいという記述は誤り',
    difficulty: 'standard',
