    id: 'ks-doboku-302', subject: 'doboku', subjectName: '土木工学',
    question: '鋼橋の腐食対策（塗装・耐候性鋼材）に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '鋼橋の防食法には、塗装（重防食塗装等）による防食のほか、耐候性鋼材（表面に緻密なさび層を形成させ、腐食の進行を抑制する鋼材）を用いる方法等がある。', explanation: '適当。鋼橋の防食法として妥当である。' },
      { key: 'B', text: '耐候性鋼材は、飛来塩分の多い海岸付近等の環境では、緻密な安定さび層が形成されにくく、通常の環境に比べて腐食が進行しやすい場合がある。', explanation: '適当。耐候性鋼材の適用上の限界として妥当である。' },
      { key: 'C', text: '塗装による防食では、塗膜の劣化（紫外線・風雨等による劣化）が経年的に進行するため、定期的な点検・塗替え等の維持管理が必要となる。', explanation: '適当。塗装の維持管理として妥当である。' },
      { key: 'D', text: '耐候性鋼材を用いた橋梁は、いかなる環境条件でも塗装等の防食を一切必要とせず、維持管理の手間がかからない万能な材料である。', explanation: '不適当。耐候性鋼材は適切な環境条件（飛来塩分量が少ない内陸部等）で効果を発揮する材料であり、海岸部等の厳しい腐食環境では十分な防食効果が得られない場合があるため、環境条件に応じた適用可否の判断や、必要に応じた追加対策の検討が必要である。' },
    ],
    correctKey: 'D',
    explanation: '鋼橋の防食は、塗装により鋼材を環境から遮断する方法と、耐候性鋼材を用いて表面に緻密な保護性さび層を形成させる方法が代表的で、ほかに溶融亜鉛めっきや金属溶射もある。塗装は重防食塗装系であっても紫外線や風雨で塗膜が劣化するため、定期点検と塗替えという維持管理が前提になる。耐候性鋼材は塗替えを減らせる一方、飛来塩分の多い海岸部や、水がかりや滞水が生じる部位では緻密なさび層が育たず層状剥離さびを生じるので、飛来塩分量などの環境条件から適用の可否を判断する必要がある。\n【図解】鋼橋の防食法の比較\n　防食法｜原理｜留意点\n　重防食塗装｜塗膜で環境から遮断する｜定期点検と塗替えが必要\n　耐候性鋼材｜緻密な保護性さび層を形成｜飛来塩分の多い環境は不利\n　溶融亜鉛めっき｜亜鉛の犠牲防食作用｜部材寸法に制約がある\n　⇒ 環境条件に応じて防食法を選定し適用可否を判断する\n　⚠ 耐候性鋼材はいかなる環境でも防食不要という記述は誤り',
    difficulty: 'standard',
