    question: 'アスファルト舗装の締固め（転圧順序・温度管理）に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'アスファルト舗装の締固めは、一般に継目転圧、初転圧（ロードローラ）、二次転圧（タイヤローラ）、仕上げ転圧（ロードローラ）の順に行われる。', explanation: '適当。締固めの一般的な転圧順序である。' },
      { key: 'B', text: '初転圧は敷き均し直後の高温時に行われ、過大な転圧圧力による混合物の側方流動（ヘアクラック等）に注意しながら行う必要がある。', explanation: '適当。初転圧の留意点として妥当である。' },
      { key: 'C', text: '二次転圧にタイヤローラを用いる場合、空気入りタイヤのニーディング作用により、混合物の密度を高める効果が期待できる。', explanation: '適当。タイヤローラのニーディング作用として妥当である。' },
      { key: 'D', text: 'アスファルト舗装の締固めは、混合物の温度にかかわらず、いつでも同じ効果が得られるため、温度管理を行う必要はない。', explanation: '不適当。アスファルト混合物の締固めは、混合物の温度が転圧に適した範囲にあるうちに行う必要があり、温度が低下しすぎると締固めが困難になり、所要の密度が得られなくなるおそれがあるため、温度管理は締固め管理上の重要な要素である。' },
    ],
    correctKey: 'D',
    explanation: 'アスファルト混合物の締固めは、継目転圧、初転圧、二次転圧、仕上げ転圧の順で行う。初転圧はロードローラにより混合物が高温のうちに行うが、温度が高すぎたり転圧圧力が過大だとヘアクラックや側方流動が生じるため注意を要する。二次転圧はタイヤローラのニーディング作用や振動ローラにより所要密度まで締め固める。仕上げ転圧はローラマークを消す目的で行う。混合物の温度が下がるとアスファルトの粘度が上がって粒子が動かなくなり所要密度が得られないため、温度管理は締固め管理上の要となる。\n【図解】アスファルト舗装の転圧工程\n　工程｜使用する機械｜ねらい\n　初転圧｜ロードローラ｜高温時に形を整える\n　二次転圧｜タイヤローラや振動ローラ｜所要密度まで締め固める\n　仕上げ転圧｜ロードローラ｜ローラマークの消去\n　⇒ 温度が下がると所要の密度が得られなくなる\n　⚠ 温度にかかわらず同じ効果が得られ温度管理は不要という記述は誤り',
