    correctKey: 'D',
    explanation: 'インターロッキングブロック舗装は、プレキャストコンクリートブロックを敷砂の上に敷き並べ、目地に細砂を充填してブロック相互のかみ合わせにより荷重を分散させる舗装である。ブロック単体ではなく、目地砂で拘束された集合体として挙動する点が特徴で、敷砂の厚さと粒度、目地幅と目地砂の充填度、周囲を押さえるエッジ拘束の管理が耐荷力を左右する。透水性ブロックとすれば雨水の地下浸透により都市型水害の軽減や地下水涵養にも寄与する。設計はブロック舗装特有の挙動を踏まえた方法によらなければならない。\n【図解】インターロッキングブロック舗装\n　要素｜役割｜管理のポイント\n　ブロック｜荷重を受けて相互にかみ合う｜形状と敷設パターン\n　目地砂｜ブロックを拘束し荷重を伝達｜目地幅と充填の程度\n　敷砂と路盤｜荷重を路床へ分散する｜厚さ、粒度、不陸整正\n　⇒ 端部のエッジ拘束が失われるとかみ合い効果が低下する\n　⚠ 通常の舗装と全く同じ設計手法をそのまま適用してよいという記述は誤り',
